            zone.ZoneServiceArea = AllAreas.Where(a => a.RateTableID == zone.Id.ToString()).ToList();
            zone.ZoneAccessorial = AllAccessorials.Where(a => a.RateTableID == zone.Id.ToString()).ToList();
        }

        table.RateTableZones = zones;
    }
}
```

