        private async Task RefreshRateTablesAsync()
        {
            try
            {
                radTreeView_TarrifRateTables.Nodes.Clear();
                var result = await _tarriffViewModel.GetRateTables();

                if (result?.Data == null)
                {
                    MessageToGUI("Failed to load data.");
                    return;
                }

                _rateTables = result.Data;
                PopulateTreeView(_rateTables);
            }
            catch (Exception ex)
            {
                MessageToGUI($"Failed to load data: {ex.Message}");
            }
        }

        private void PopulateTreeView(List<RateTableDto> rateTables)
        {
            foreach (var rate in rateTables)
            {
                var rateNode = CreateTreeNode(rate.TarriffTableName, rate, "rate");

                foreach (var zone in rate.RateTableZones ?? new())
                {
                    var zoneNode = CreateTreeNode(zone.ZoneName, zone, "zone");

                    foreach (var rule in zone.ZonePricingRule ?? new())
                    {
                        var ruleNode = CreateTreeNode(rule.RuleName, rule, "rule");
                        zoneNode.Nodes.Add(ruleNode);
                    }

                    rateNode.Nodes.Add(zoneNode);
                }

                radTreeView_TarrifRateTables.Nodes.Add(rateNode);
            }

            radTreeView_TarrifRateTables.ExpandAll();
        }

        private RadTreeNode CreateTreeNode(string text, object data, string type)
        {
            return new RadTreeNode(text)
            {
                Text = text,
                Value = text,
                Tag = new TreeViewNodeModel
                {
                    id = (data as BaseObject)?.Id ?? Guid.NewGuid(),
                    modelType = type,
                    returnData = data,
                    parentRateTable = _currentRateTable
                },
                ContextMenu = GetTreeViewContextMenu(new TreeViewNodeModel { returnData = data, modelType = type })
            };
