            var selectedItem = comboStateDropdown.SelectedItem;
            var code = selectedItem.GetType().GetProperty("Code")?.GetValue(selectedItem, null)?.ToString();

            var confirm = MessageBox.Show("Are you sure you want to continue?", "Confirmation", MessageBoxButtons.YesNo, MessageBoxIcon.Question);
            if (confirm != DialogResult.Yes) return;

            var result = await _tarriffViewModel.ReplaceZoneAreas(code, _currentRateTable, _currentZone.Id);
            MessageToGUI(result.Message);
        }

