public class UniverseHub<T> : IUniverseHub<T>
{
    private readonly List<Subscription<T>> _subscriptions = new();
    private readonly object _lock = new();
    private readonly Func<T, string> _hashFunc;
    private string _lastHash = string.Empty;
    private int _changeThreshold = 1; // Could be adapted dynamically
    private int _changeCounter = 0;

    public UniverseHub(Func<T, string> hashFunc)
    {
        _hashFunc = hashFunc;
    }

    public void OnNext(T input)
    {
        lock (_lock)
        {
            var currentHash = _hashFunc(input);
            if (_lastHash != currentHash)
            {
                _changeCounter++;
                _lastHash = currentHash;

                foreach (var sub in _subscriptions)
                {
                    if (sub.Filter(input))
                        sub.OnReceive(input);
                }
            }

            if (_changeCounter >= _changeThreshold)
            {
                Stabilize();
                _changeCounter = 0;
            }
        }
    }

    public IDisposable Subscribe(Func<T, bool> filter, Action<T> onReceive)
    {
        var sub = new Subscription<T>(filter, onReceive);
        lock (_lock) _subscriptions.Add(sub);
        return new Unsubscriber<T>(_subscriptions, sub, _lock);
    }

    public void Stabilize()
    {
        // Trigger feedback, save, or reflect
        Console.WriteLine("[UniverseHub] Stabilizing...");
    }

    private class Subscription<TSub>
    {
        public Func<TSub, bool> Filter { get; }
        public Action<TSub> OnReceive { get; }

        public Subscription(Func<TSub, bool> filter, Action<TSub> onReceive)
        {
            Filter = filter;
            OnReceive = onReceive;
        }
    }

    private class Unsubscriber<TSub> : IDisposable
    {
        private readonly List<Subscription<TSub>> _subs;
        private readonly Subscription<TSub> _target;
        private readonly object _lock;

        public Unsubscriber(List<Subscription<TSub>> subs, Subscription<TSub> target, object lockObj)
        {
            _subs = subs;
            _target = target;
            _lock = lockObj;
        }

        public void Dispose()
        {
            lock (_lock)
            {
                _subs.Remove(_target);
            }
        }
    }
}"}

